shell_commands.command:
cd /testbed && git apply --recount <<'PATCH'
diff --git a/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java b/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
--- a/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
+++ b/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
@@ -629,6 +629,76 @@
     }

+    @Test
+    public void cancelBeforeInnerOnSubscribe() throws Throwable {
+        TestHelper.withErrorTracking(errors -> {
+            for (boolean delayErrors : new boolean[] { false, true }) {
+                PublishSubject<Integer> ps = PublishSubject.create();
+                PublishSubject<Integer> inner = PublishSubject.create();
+                TestObserver<Integer> to = new TestObserver<>();
+                AtomicInteger seeds = new AtomicInteger();
+
+                Observable<Integer> mapped = Observable.defer(() -> {
+                    to.dispose();
+                    return inner.scan(0, (a, b) -> a + b)
+                            .map(v -> {
+                                seeds.incrementAndGet();
+                                return v;
+                            });
+                });
+
+                Observable<Integer> result = delayErrors
+                        ? ps.switchMapDelayError(v -> mapped)
+                        : ps.switchMap(v -> mapped);
+                result.subscribe(to);
+
+                ps.onNext(1);
+
+                to.assertEmpty();
+                assertTrue(to.isDisposed());
+                assertEquals(1, seeds.get());
+                assertFalse(ps.hasObservers());
+                assertFalse(inner.hasObservers());
+            }
+            assertTrue(errors.toString(), errors.isEmpty());
+        });
+    }
+
+    @Test
+    public void cancelInnerOnSubscribeRace() throws Throwable {
+        TestHelper.withErrorTracking(errors -> {
+            for (boolean delayErrors : new boolean[] { false, true }) {
+                for (int i = 0; i < TestHelper.RACE_DEFAULT_LOOPS; i++) {
+                    PublishSubject<Integer> ps = PublishSubject.create();
+                    PublishSubject<Integer> inner = PublishSubject.create();
+                    Observable<Integer> mapped = Observable.defer(() ->
+                            inner.scan(0, (a, b) -> a + b).map(v -> v));
+
+                    Observable<Integer> result = delayErrors
+                            ? ps.switchMapDelayError(v -> mapped)
+                            : ps.switchMap(v -> mapped);
+                    TestObserver<Integer> to = result.test();
+
+                    TestHelper.race(() -> ps.onNext(1), () -> to.dispose());
+
+                    to.assertNoErrors().assertNotComplete();
+                    assertTrue(to.values().size() <= 1);
+                    assertTrue(to.isDisposed());
+                    assertFalse(ps.hasObservers());
+                    assertFalse(inner.hasObservers());
+                }
+            }
+            assertTrue(errors.toString(), errors.isEmpty());
+        });
+    }
+
     @Test
     public void switchMapSingleJustSource() {
         Observable.just(0)
PATCH
./gradlew --offline test --tests io.reactivex.rxjava3.internal.operators.observable.ObservableSwitchTest.cancelBeforeInnerOnSubscribe

