--- a/src/main/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchMap.java
+++ b/src/main/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchMap.java
@@ -350,9 +350,13 @@
         @Override
         public void onNext(R t) {
             if (index == parent.unique) {
-                if (t != null) {
-                    queue.offer(t);
+                // The queue is not initialized if cancellation wins before onSubscribe.
+                SimpleQueue<R> q = queue;
+                if (q != null) {
+                    if (t != null) {
+                        q.offer(t);
+                    }
+                    parent.drain();
                 }
-                parent.drain();
             }
         }
PATCH
./gradlew --offline test --tests io.reactivex.rxjava3.internal.operators.observable.ObservableSwitchTest && git diff --check && git --no-pager diff --stat

